describe('Search Filter by Category', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should filter search results by selecting category checkboxes', () => {
    // Verify initial search results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Select 'Electronics' category checkbox
    cy.get('[data-testid="category-checkbox-electronics"]').click();
    cy.get('[data-testid="category-checkbox-electronics"]').should('be.checked');

    // Select 'Books' category checkbox
    cy.get('[data-testid="category-checkbox-books"]').click();
    cy.get('[data-testid="category-checkbox-books"]').should('be.checked');

    // Verify search results are filtered and updated
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="result-item"]').first().should('contain', 'Electronics');
    cy.get('[data-testid="result-item"]').first().should('contain', 'Books');

    // Verify filter applied to URL
    cy.url().should('include', '?category=electronics,books');

    // Verify filter count is displayed
    cy.get('[data-testid="filter-count"]').should('contain', '2');
  });

  it('should handle unchecking a category filter and update results', () => {
    // Select 'Electronics' category checkbox
    cy.get('[data-testid="category-checkbox-electronics"]').click();
    cy.get('[data-testid="category-checkbox-electronics"]').should('be.checked');

    // Verify results are filtered
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Uncheck 'Electronics' category checkbox
    cy.get('[data-testid="category-checkbox-electronics"]').click();
    cy.get('[data-testid="category-checkbox-electronics"]').should('not. be.checked');

    // Verify results are updated after unchecking
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);
    cy.get('[data-testid="result-item"]').first().should('not.contain', 'Electronics');

    // Verify filter is removed from URL
    cy.url().should('not.include', '?category=electronics');

    // Verify filter count is updated
    cy.get('[data-testid="filter-count"]').should('contain', '1');
  });
});
